<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { ConceptoFlujoCaja, ConceptoFlujoCajaPayload } from '../interfaces/concepto-flujo-caja.interface'
import { cambiarEstadoConceptoFlujoCaja, guardarConceptoFlujoCaja, listarConceptosFlujoCaja, obtenerConceptoFlujoCaja } from '../services/concepto-flujo-caja'

const rows = ref<ConceptoFlujoCaja[]>([]), search = ref(''), activity = ref(''), nature = ref(''), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const form = reactive<ConceptoFlujoCajaPayload>({ codigo: '', nombre: '', actividad: 'OPERACION', naturaleza: 'INGRESO', orden: 0 })
const filtered = computed(() => { const q = search.value.toLocaleUpperCase(); return rows.value.filter(x => (!q || `${x.codigo} ${x.nombre}`.includes(q)) && (!activity.value || x.actividad === activity.value) && (!nature.value || x.naturaleza === nature.value)) })
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { rows.value = await listarConceptosFlujoCaja() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, { codigo: '', nombre: '', actividad: 'OPERACION', naturaleza: 'INGRESO', orden: 0 }); showForm.value = true }
async function edit(item: ConceptoFlujoCaja) { loading.value = true; try { const value = await obtenerConceptoFlujoCaja(item.id); editing.value = value.id; Object.assign(form, { codigo: value.codigo, nombre: value.nombre, actividad: value.actividad, naturaleza: value.naturaleza, orden: value.orden }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { loading.value = true; error.value = ''; try { await guardarConceptoFlujoCaja(editing.value, { ...form }); success.value = `Concepto de flujo de caja ${editing.value ? 'actualizado' : 'registrado'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: ConceptoFlujoCaja) { const action = item.activo ? 'inactivar' : 'activar'; if (!confirm(`¿Desea ${action} ${item.nombre}?`)) return; loading.value = true; try { await cambiarEstadoConceptoFlujoCaja(item.id); success.value = `Concepto ${item.activo ? 'inactivado' : 'activado'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function clear() { search.value = ''; activity.value = ''; nature.value = '' }
onMounted(load)
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Conceptos de flujo de caja</nav><header class="hero"><div class="mark">CF</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Conceptos de flujo de caja</h1><p>Clasificación de ingresos y salidas por actividad financiera.</p></div><strong>{{filtered.length}} registros</strong><button @click="create">+ Nuevo concepto</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="filters"><input v-model.trim="search" placeholder="Buscar por código o nombre"><select v-model="activity"><option value="">Todas las actividades</option><option value="OPERACION">Operación</option><option value="INVERSION">Inversión</option><option value="FINANCIAMIENTO">Financiamiento</option></select><select v-model="nature"><option value="">Todas las naturalezas</option><option value="INGRESO">Ingreso</option><option value="SALIDA">Salida</option></select><button class="soft" @click="clear">Limpiar</button></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!filtered.length" class="empty">No se encontraron conceptos de flujo de caja.</div><div v-else class="scroll"><table><thead><tr><th>Orden</th><th>Código</th><th>Nombre</th><th>Actividad</th><th>Naturaleza</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td>{{item.orden}}</td><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td><span class="activity">{{item.actividad}}</span></td><td><span :class="item.naturaleza==='INGRESO'?'income':'expense'">{{item.naturaleza}}</span></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} concepto de flujo de caja</h2></div><button type="button" @click="showForm=false">×</button></header><div class="twocol"><label>Código<input v-model.trim="form.codigo" maxlength="10" required placeholder="Ej. OPE-01"></label><label>Orden<input v-model.number="form.orden" type="number" min="0" step="1" required></label></div><label>Nombre<input v-model.trim="form.nombre" maxlength="150" required placeholder="Nombre del concepto"></label><div class="twocol"><label>Actividad<select v-model="form.actividad" required><option value="OPERACION">Operación</option><option value="INVERSION">Inversión</option><option value="FINANCIAMIENTO">Financiamiento</option></select></label><label>Naturaleza<select v-model="form.naturaleza" required><option value="INGRESO">Ingreso</option><option value="SALIDA">Salida</option></select></label></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>

<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse;font-size:.51rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}.good,.bad,.income,.expense,.activity{display:inline-block;padding:4px 8px;border-radius:10px;font-size:.45rem;font-weight:800}.good,.income{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.expense{color:#99453e;background:#fcede9}.activity{color:#3b6273;background:#e8f2f6}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(560px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;color:#5d7078;font-size:.52rem;font-weight:700}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
